INSERT INTO speed_his(
                       user_idx
                     , practice_type
                     , speed
                     , accuracy
                     , duration
                     , use_yn
                     , ins_idx
                     , ins_date
) VALUES (
                #{userIdx}
              , #{practiceType}
              , #{speed}
              , #{accuracy}
              , #{duration}
              , 'Y'
              , #{userIdx}
              , NOW()
                 )

